    ts: ctx.latestTs,
    values: {
        "waterConsumption": getConsumption()
    }
}


function getConsumption() {
    if (pulseCounter.count() == 1) {
        return pulseCounter.first();
    }
    if (pulseCounter.count() < 2) {
        return 0;
    }
    var first = pulseCounter.first();
    var last = pulseCounter.last();


    if (isNaN(first) || isNaN(last)) {
        return 0;
    }

    var waterConsumption = last - first;
    if (waterConsumption <= 0) {
        return 0;
    }

    return toFixed(waterConsumption, 2);
}
